from solution import round_num


def test_issue_example_4722_10():
    """Round to nearest multiple as in example 4722 to nearest 10 is 4720."""
    assert round_num(4722, 10) == 4720  # 4722/10=472.2 -> 472*10=4720


def test_issue_exact_multiple_unchanged():
    """Round the given number already a multiple stays at same multiple."""
    assert round_num(4730, 10) == 4730  # 4730/10=473 -> 473*10=4730


def test_issue_just_below_halfway():
    """Value just below halfway rounds down to nearest multiple."""
    assert round_num(4724, 10) == 4720  # 4724/10=472.4 -> 472*10=4720


def test_issue_just_above_halfway():
    """Value just above halfway rounds up to nearest multiple."""
    assert round_num(4726, 10) == 4730  # 4726/10=472.6 -> 473*10=4730


def test_issue_below_midpoint_step_5():
    """Round 12 to nearest multiple of 5 is 10."""
    assert round_num(12, 5) == 10  # multiples 10,15 distances 2 vs 3 -> 10


def test_issue_above_midpoint_step_5():
    """Round 13 to nearest multiple of 5 is 15."""
    assert round_num(13, 5) == 15  # multiples 10,15 distances 3 vs 2 -> 15


def test_issue_large_step_rounds_down():
    """Round 4722 to nearest multiple of 100 is 4700."""
    assert round_num(4722, 100) == 4700  # multiples 4700,4800 distances 22 vs 78 -> 4700


def test_issue_large_step_rounds_up():
    """Round 4770 to nearest multiple of 100 is 4800."""
    assert round_num(4770, 100) == 4800  # multiples 4700,4800 distances 70 vs 30 -> 4800


def test_issue_zero_rounds_to_zero():
    """Round zero to nearest multiple of 10 is zero."""
    assert round_num(0, 10) == 0  # 0/10=0 -> 0*10=0


def test_issue_negative_toward_zero():
    """Round negative -4722 to nearest multiple of 10 is -4720."""
    assert round_num(-4722, 10) == -4720  # multiples -4730,-4720 distances 8 vs 2 -> -4720


def test_issue_negative_away_from_zero():
    """Round negative -4726 to nearest multiple of 10 is -4730."""
    assert round_num(-4726, 10) == -4730  # multiples -4730,-4720 distances 4 vs 6 -> -4730


def test_contract_result_is_multiple():
    """Nearest multiple result must itself be a multiple of m."""
    assert round_num(4726, 10) % 10 == 0  # 4726 nearest 10 is 4730, 4730%10=0


def test_contract_step_one_identity():
    """Rounding to nearest multiple of 1 returns n unchanged."""
    assert round_num(9, 1) == 9  # 9/1=9 -> 9*1=9
